
const WORDS=[{"id": 0, "w": "北极", "p": "běijí", "t": "名词", "m": "Bắc Cực", "coll": "北极地区、北极考察", "s": "这组照片记录了北极地区的景象，让观众看到了遥远世界的一角。"}, {"id": 1, "w": "评论", "p": "pínglùn", "t": "动词", "m": "bình luận, nhận xét", "coll": "发表评论、评论作品", "s": "评论一部作品时，我们应当说明依据，而不只是表达喜恶。"}, {"id": 2, "w": "典型", "p": "diǎnxíng", "t": "名词", "m": "điển hình, gương điển hình", "coll": "典型案例、典型代表", "s": "老师选择了一个典型案例，帮助学生理解讨论中的关键问题。"}, {"id": 3, "w": "考察", "p": "kǎochá", "t": "动词", "m": "khảo sát, quan sát tỉ mỉ", "coll": "实地考察、考察环境", "s": "正式制定方案以前，研究团队先进行了细致的实地考察。"}, {"id": 4, "w": "访问", "p": "fǎngwèn", "t": "动词", "m": "phỏng vấn, đi thăm", "coll": "访问学者、访问当地居民", "s": "记者访问了当地居民，了解他们对生活变化的看法。"}, {"id": 5, "w": "高峰", "p": "gāofēng", "t": "名词", "m": "đỉnh cao", "coll": "攀登高峰、创作高峰", "s": "这部作品标志着他的创作进入了一个新的高峰。"}, {"id": 6, "w": "毅然", "p": "yìrán", "t": "副词", "m": "kiên quyết, cương quyết", "coll": "毅然决定、毅然离开", "s": "经过慎重考虑，她毅然决定离开熟悉的环境，去尝试新的生活。"}, {"id": 7, "w": "疲惫", "p": "píbèi", "t": "形容词", "m": "mệt mỏi, mệt nhọc", "coll": "感到疲惫、疲惫不堪", "s": "连续赶路以后，大家都感到十分疲惫，决定先休息一晚。"}, {"id": 8, "w": "力所能及", "p": "lìsuǒnéngjí", "t": "成语", "m": "nằm trong khả năng", "coll": "力所能及的事、力所能及的帮助", "s": "面对他人的困难，我们可以从力所能及的事做起，给予实际的帮助。"}, {"id": 9, "w": "开拓", "p": "kāituò", "t": "动词", "m": "mở rộng, phát triển, khai thác", "coll": "开拓视野、开拓市场", "s": "企业希望通过改进产品，逐步开拓市场，赢得更多顾客的认可。"}, {"id": 10, "w": "职务", "p": "zhíwù", "t": "名词", "m": "chức vụ", "coll": "担任职务、辞去职务", "s": "他虽然不再担任原来的职务，却依然积极参与相关工作。"}, {"id": 11, "w": "捆绑", "p": "kǔnbǎng", "t": "动词", "m": "trói, buộc", "coll": "捆绑行李、捆绑结实", "s": "装车之前，工作人员把行李捆绑结实，防止运输途中滑落。"}, {"id": 12, "w": "释放", "p": "shìfàng", "t": "动词", "m": "thả ra, phóng thích", "coll": "释放压力、释放信号", "s": "适当的休息有助于释放压力，让我们以更好的状态投入工作。"}, {"id": 13, "w": "出身", "p": "chūshēn", "t": "名词", "m": "sự xuất thân, lai lịch", "coll": "家庭出身、出身普通", "s": "他出身普通，却凭借长期的努力，逐步实现了自己的理想。"}, {"id": 14, "w": "鼓动", "p": "gǔdòng", "t": "动词", "m": "động viên, khuyến khích", "coll": "鼓动大家、受到鼓动", "s": "在朋友的鼓动下，他终于走上舞台，唱起了熟悉的歌。"}, {"id": 15, "w": "夫妇", "p": "fūfù", "t": "名词", "m": "vợ chồng", "coll": "一对夫妇、年轻夫妇", "s": "这对年轻夫妇共同经营一家小店，每天都忙得十分充实。"}, {"id": 16, "w": "头脑", "p": "tóunǎo", "t": "名词", "m": "đầu óc", "coll": "保持清醒的头脑、开动头脑", "s": "面对复杂的信息，我们需要保持清醒的头脑，认真判断其中的依据。"}, {"id": 17, "w": "遭遇", "p": "zāoyù", "t": "动词", "m": "gặp phải", "coll": "遭遇困难、遭遇风暴", "s": "船只在返航途中遭遇风暴，不得不调整航线。"}, {"id": 18, "w": "灾难", "p": "zāinàn", "t": "名词", "m": "tai họa, tai ương", "coll": "自然灾难、避免灾难", "s": "这场灾难使许多家庭失去了住所，也让救援工作面临巨大压力。"}, {"id": 19, "w": "饥饿", "p": "jī'è", "t": "形容词", "m": "đói", "coll": "感到饥饿、饥饿难忍", "s": "走了很长一段路后，他感到十分饥饿，拿出随身带的食物。"}, {"id": 20, "w": "风暴", "p": "fēngbào", "t": "名词", "m": "gió bão, giông bão", "coll": "一场风暴、风暴来临", "s": "风暴来临之前，渔民们及时返回港口，把船停在安全的地方。"}, {"id": 21, "w": "严寒", "p": "yánhán", "t": "形容词", "m": "giá rét", "coll": "抵御严寒、不畏严寒", "s": "为了抵御严寒，考察队员穿上厚厚的衣服，做好出发准备。"}, {"id": 22, "w": "惊奇", "p": "jīngqí", "t": "形容词", "m": "kinh ngạc, sửng sốt", "coll": "感到惊奇、令人惊奇", "s": "看到冰面下奇特的颜色，大家感到十分惊奇，纷纷停下来观察。"}, {"id": 23, "w": "记载", "p": "jìzǎi", "t": "动词", "m": "ghi chép, ghi lại", "coll": "详细记载、史书记载", "s": "这本日记详细记载了他在旅途中遇到的人和事。"}, {"id": 24, "w": "差别", "p": "chābié", "t": "名词", "m": "sự khác biệt", "coll": "存在差别、明显差别", "s": "两种方法虽然目标相同，在具体操作上却存在明显差别。"}, {"id": 25, "w": "连锁", "p": "liánsuǒ", "t": "形容词", "m": "dây chuyền, chuỗi", "coll": "连锁反应、连锁商店", "s": "一个环节的变化，可能引起连锁反应，因此必须全面考虑。"}, {"id": 26, "w": "包装", "p": "bāozhuāng", "t": "动词／名词", "m": "đóng gói; bao bì", "coll": "产品包装、重新包装", "s": "为了减少浪费，这家店重新设计了包装，尽量使用可回收材料。"}, {"id": 27, "w": "衣裳", "p": "yīshang", "t": "名词", "m": "quần áo", "coll": "换上衣裳、洗净衣裳", "s": "外婆把洗净的衣裳晾在院子里，等待阳光把它们晒干。"}, {"id": 28, "w": "潇洒", "p": "xiāosǎ", "t": "形容词", "m": "phóng khoáng và thanh lịch", "coll": "举止潇洒、潇洒自如", "s": "画家挥笔时潇洒自如，几笔之间，山水的轮廓便出现了。"}, {"id": 29, "w": "本能", "p": "běnnéng", "t": "名词", "m": "bản năng", "coll": "保护本能、生存本能", "s": "听见巨响，他出于本能，立刻向安全的地方退去。"}, {"id": 30, "w": "冲动", "p": "chōngdòng", "t": "名词／形容词", "m": "sự thôi thúc, sự thúc đẩy", "coll": "一时冲动、控制冲动", "s": "他克制住一时的冲动，决定先了解情况，再作判断。"}, {"id": 31, "w": "相差", "p": "xiāngchà", "t": "动词", "m": "khác nhau", "coll": "相差很大、相差不多", "s": "这两种设备外形相似，实际性能却相差很大。"}, {"id": 32, "w": "古董", "p": "gǔdǒng", "t": "名词", "m": "đồ cổ", "coll": "收藏古董、一件古董", "s": "这件古董不仅工艺精细，也反映了当时的生活习惯。"}, {"id": 33, "w": "在意", "p": "zài yì", "t": "动词", "m": "để ý, quan tâm", "coll": "在意评价、毫不在意", "s": "她不太在意外界的议论，更关心自己的工作是否有实际价值。"}, {"id": 34, "w": "捕捉", "p": "bǔzhuō", "t": "动词", "m": "bắt, tóm", "coll": "捕捉瞬间、捕捉信息", "s": "摄影师耐心等待，希望捕捉到动物奔跑的精彩瞬间。"}, {"id": 35, "w": "赤道", "p": "chìdào", "t": "名词", "m": "xích đạo", "coll": "赤道附近、赤道地区", "s": "这部纪录片介绍了赤道附近几个地区不同的自然景观。"}, {"id": 36, "w": "专题", "p": "zhuāntí", "t": "名词", "m": "chuyên đề", "coll": "专题报道、专题研究", "s": "杂志推出了一组专题报道，介绍传统手工艺人的生活。"}, {"id": 37, "w": "抢救", "p": "qiǎngjiù", "t": "动词", "m": "giải cứu, cứu nguy, cứu vãn", "coll": "抢救伤员、抢救资料", "s": "工作人员在大雨到来之前，及时抢救了仓库里的珍贵资料。"}, {"id": 38, "w": "刻不容缓", "p": "kèbùrónghuǎn", "t": "成语", "m": "vô cùng khẩn cấp, không thể chậm trễ", "coll": "刻不容缓、保护工作刻不容缓", "s": "古建筑已经出现严重损坏，修复和保护工作刻不容缓。"}, {"id": 39, "w": "支出", "p": "zhīchū", "t": "名词／动词", "m": "phí tổn", "coll": "减少支出、日常支出", "s": "他们记录每一笔日常支出，以便合理安排旅行经费。"}, {"id": 40, "w": "精打细算", "p": "jīngdǎ xìsuàn", "t": "成语", "m": "tính toán kỹ lưỡng", "coll": "精打细算、精打细算过日子", "s": "为了完成这次旅行，她在日常生活中精打细算，逐渐攒够了费用。"}, {"id": 41, "w": "开支", "p": "kāizhī", "t": "名词", "m": "khoản chi, tiền tiêu", "coll": "节省开支、生活开支", "s": "改进管理以后，机构在不影响服务的前提下，减少了不必要的开支。"}, {"id": 42, "w": "免得", "p": "miǎnde", "t": "连词", "m": "để tránh, đỡ phải", "coll": "免得忘记、免得误会", "s": "重要的信息最好写下来，免得忙起来以后忘记。"}, {"id": 43, "w": "储蓄", "p": "chǔxù", "t": "动词／名词", "m": "tiền để dành", "coll": "个人储蓄、储蓄习惯", "s": "他用多年的储蓄，支持了这项自己热爱的拍摄计划。"}, {"id": 44, "w": "穿越", "p": "chuānyuè", "t": "动词", "m": "đi qua, xuyên qua", "coll": "穿越沙漠、穿越森林", "s": "队员们在向导的带领下，穿越森林，抵达了山脚下的村庄。"}, {"id": 45, "w": "腹泻", "p": "fùxiè", "t": "动词", "m": "bị tiêu chảy", "coll": "出现腹泻、腹泻症状", "s": "调查表记录了受访者是否出现腹泻，以及症状开始的时间。"}, {"id": 46, "w": "时常", "p": "shícháng", "t": "副词", "m": "thường xuyên", "coll": "时常想起、时常联系", "s": "离开家乡以后，她仍然时常想起小时候生活过的院子。"}, {"id": 47, "w": "将就", "p": "jiāngjiu", "t": "动词", "m": "tạm, đỡ, chịu theo", "coll": "暂时将就、将就着用", "s": "新的设备还没有送到，大家只好先用旧的将就一下。"}, {"id": 48, "w": "支配", "p": "zhīpèi", "t": "动词", "m": "sắp đặt, điều khiển", "coll": "自由支配、支配时间", "s": "周末，他终于有了一段可以自由支配的时间。"}, {"id": 49, "w": "执着", "p": "zhízhuó", "t": "形容词", "m": "cố chấp, kiên trì", "coll": "执着追求、执着的信念", "s": "正是对理想的执着追求，使他在遇到困难时，仍然坚持了下来。"}];
